#!/usr/bin/env python3
"""Cat diagnosis_ja enrichment — batch 11 (50 entries)."""
import json
import os
import time

JSON_PATH = os.path.join(os.path.dirname(os.path.dirname(os.path.abspath(__file__))), "diseases_all_species.json")

ENRICHMENTS: dict[str, dict[str, str]] = {}

ENRICHMENTS["cat_feline_liver_fluke_infection_opisthorchis"] = {"diagnosis_ja": "慢性嘔吐・下痢・黄疸・体重減少を呈する。生魚摂取歴を確認。血液化学でALP/GGT上昇、T-Bil上昇を認める。糞便検査で小型楕円形の蓋付き虫卵を検出（沈殿法が浮遊法より感度高い）。腹部超音波で胆管拡張・肝臓のエコー輝度変化を確認。CBC好酸球増多を認めることがある。慢性感染では胆管癌のリスク上昇。胆管炎、肝リピドーシス、膵炎との鑑別が必要。"}
ENRICHMENTS["cat_feline_cheyletiellosis_walking_dandruff"] = {"diagnosis_ja": "背部を中心とした著明な落屑（フケ）・軽度搔痒を認める。「歩くフケ」として知られ、フケが動いて見えることがある。皮膚掻爬検査またはセロハンテープ法でCheyletiella blakeiの虫体・卵を検出。蚤取り櫛でフケを収集しKOH処理後に鏡検。皮膚生検は非特異的（好酸球性表皮炎）。接触動物のスクリーニングが重要（人畜共通感染症）。ノミアレルギー、皮膚糸状菌症、脂漏症との鑑別が必要。"}
ENRICHMENTS["cat_feline_trombiculiasis_chigger_mite"] = {"diagnosis_ja": "季節性（夏〜秋）の激しい搔痒・紅斑性丘疹を認める。好発部位は耳介・趾間・腹部。橙〜赤色の微小なダニ幼虫を肉眼で確認できることがある。皮膚掻爬検査でTrombicula autumnalis（ツツガムシ）の六脚幼虫を検出。皮膚生検では非特異的な好酸球性皮膚炎を認める。発生地域・季節の情報が診断に有用。ノミ刺症、食物アレルギー、ツメダニ症との鑑別が必要。人にも刺咬被害（紅斑性丘疹）を起こす。"}
ENRICHMENTS["cat_feline_myiasis_fly_strike"] = {"diagnosis_ja": "被毛の汚染部位・開放創に蠅蛆（ウジ）の寄生を確認。高齢・衰弱・失禁・外傷のある猫に好発。創部の剃毛で蛆虫と壊死組織を直接確認。蛆虫の種類同定（Calliphoridae等）は疫学的に重要。創部の細菌培養で二次感染を評価。CBC白血球増多は全身性炎症を反映。創傷の深さと範囲の評価。基礎疾患（糖尿病、腫瘍、運動障害）の検索が重要。創傷感染、皮膚腫瘍（潰瘍化）との鑑別が必要。"}
ENRICHMENTS["cat_feline_demodex_gatoi_infection"] = {"diagnosis_ja": "全身性の搔痒・脱毛・発赤を呈する。D. gatoi（短体型、表皮寄生）は接触感染するため多頭飼育環境で流行。浅い皮膚掻爬検査（角質層のみ）で短い虫体を検出（見逃しやすく複数部位の検査が必要）。セロハンテープ法も有用。糞便検査で経口摂取した虫体を検出できることがある。石灰硫黄液への治療反応で診断的治療。D. cati（長体型、毛包寄生）とは形態が異なる。アレルギー性皮膚炎、皮膚糸状菌症との鑑別が必要。"}
ENRICHMENTS["cat_feline_dry_eye_keratoconjunctivitis_sicca"] = {"diagnosis_ja": "粘液膿性眼脂・結膜充血・角膜混濁・角膜血管新生を認める。シルマー涙液試験で涙液量低下（<5mm/min）を確認。フルオレセイン染色で角膜上皮欠損を評価。ローズベンガル染色で角膜・結膜上皮変性を検出。眼圧測定で緑内障を除外。FHV-1 PCR検査でウイルス性原因を評価（猫のKCSはFHV-1関連が多い）。免疫介在性、薬剤性（スルファサラジン）の原因検索。結膜炎、好酸球性角結膜炎との鑑別が必要。"}
ENRICHMENTS["cat_feline_anterior_uveitis"] = {"diagnosis_ja": "眼痛（羞明・流涙・眼瞼痙攣）、結膜充血、縮瞳、房水フレア・前房蓄膿を認める。細隙灯検査で房水中の炎症細胞・フレアを確認。眼圧測定で二次性緑内障（上昇）または毛様体機能低下（低下）を評価。FeLV/FIV検査、FIP抗体価・PCR、トキソプラズマIgM/IgG、全身性真菌検査で基礎疾患を検索。CBC/血液化学で全身性炎症を評価。虹彩腫瘍（メラノーマ、リンパ腫）の眼底検査。感染性vs非感染性の鑑別が重要。"}
ENRICHMENTS["cat_feline_posterior_synechia"] = {"diagnosis_ja": "虹彩と水晶体前嚢の癒着による瞳孔変形（不整瞳孔）を認める。前部ぶどう膜炎の続発症として発生。細隙灯検査で癒着部位を詳細に確認。散瞳薬（トロピカミド）投与で瞳孔の不完全散瞳を確認（癒着部位は散瞳しない）。眼圧測定で瞳孔ブロック緑内障を評価（360°癒着時は眼圧上昇）。超音波検査で後嚢癒着・水晶体変位を確認。基礎疾患（FIP、トキソプラズマ、リンパ腫）の検索。白内障、水晶体脱臼との鑑別が必要。"}
ENRICHMENTS["cat_feline_eyelid_tumor"] = {"diagnosis_ja": "眼瞼縁の結節性腫瘤として触知。流涙・結膜炎・角膜刺激を伴うことがある。細隙灯検査で腫瘤の位置・サイズ・眼瞼縁との関係を評価。FNA細胞診で扁平上皮癌（最も多い）、肥満細胞腫、リンパ腫を鑑別。切除生検による組織病理で確定。眼圧測定・眼底検査で眼球への浸潤を除外。マイボーム腺腫（犬で多い）は猫では稀。眼瞼霰粒腫、麦粒腫（マイボーム腺炎）との鑑別が必要。FIV関連腫瘍の可能性を評価。"}
ENRICHMENTS["cat_feline_progressive_retinal_atrophy"] = {"diagnosis_ja": "進行性の視力低下・夜盲（暗所での行動異常）を認める。アビシニアン、ペルシャに品種素因。眼底検査で網膜血管の狭細化、タペタム反射亢進（網膜菲薄化による）、視神経乳頭蒼白化を確認。網膜電図（ERG）で網膜機能の定量評価（杆体・錐体応答の減弱〜消失）。遺伝子検査で特定の変異を同定（rdAc, CEP290等）。白内障の二次性発症を評価。タウリン欠乏性網膜変性（FCRD）、緑内障、視神経炎との鑑別が必要。"}
ENRICHMENTS["cat_feline_hyphema"] = {"diagnosis_ja": "前房内の出血（赤色沈殿物〜前房全体の赤染）を認める。外傷歴の確認。細隙灯検査で出血量・凝血塊を評価。眼圧測定で続発性緑内障を確認。超音波検査で水晶体脱臼・眼球内腫瘤・網膜剥離を検索。CBC/凝固系検査（PT/APTT/血小板数）で出血素因を評価。血圧測定で全身性高血圧を確認（CKD、甲状腺機能亢進症関連）。FeLV/FIV検査。ぶどう膜炎、眼球内腫瘍、外傷性出血、凝固障害の鑑別が重要。"}
ENRICHMENTS["cat_feline_keratitis_non-herpetic"] = {"diagnosis_ja": "角膜混濁・充血・流涙・眼痛を認める。FHV-1関連を除外した角膜炎。フルオレセイン染色で角膜上皮欠損のパターンを評価（点状vs潰瘍性）。角膜擦過細胞診で好酸球（好酸球性角膜炎）、細菌、真菌を検索。シルマー涙液試験でKCSを除外。細菌培養・感受性試験（特にPseudomonas疑いの場合）。角膜実質溶解像（melting cornea）は緊急。FHV-1 PCR陰性確認。外傷性、免疫介在性、化学損傷との鑑別が必要。"}
ENRICHMENTS["cat_feline_symblepharon"] = {"diagnosis_ja": "結膜と角膜または結膜間の癒着を認める。FHV-1感染の後遺症として最も多い。細隙灯検査で癒着の範囲・深さを評価。フルオレセイン染色で癒着下の角膜上皮欠損を確認。鼻涙管洗浄で涙液排泄路の閉塞を評価。シルマー涙液試験で涙液量を測定。FHV-1 PCR検査で活動性感染を確認。視力評価（重度の癒着は視軸を遮る）。手術的剥離は再癒着リスクが高い。角膜潰瘍、好酸球性角結膜炎との鑑別が必要。"}
ENRICHMENTS["cat_feline_stomatitis_non-lymphoplasmacytic"] = {"diagnosis_ja": "口腔内の発赤・腫脹・潰瘍・疼痛による流涎・食欲不振を認める。リンパ形質細胞性口内炎以外の口内炎。口腔内検査で病変の分布（歯肉・頬粘膜・舌）を確認。生検による組織病理で好中球性、好酸球性、肉芽腫性など組織学的分類を実施。FIV/FeLV検査。FCV PCR検査でカリシウイルスを検索。CBC/血液化学で全身性疾患を評価。腎不全に伴う尿毒症性口内炎（BUN/Cre）を除外。口腔腫瘍、好酸球性肉芽腫との鑑別が必要。"}
ENRICHMENTS["cat_feline_salivary_gland_mucocele"] = {"diagnosis_ja": "顎下〜頸部の波動性腫脹を認める。無痛性で緩徐に増大。穿刺吸引で粘稠な透明〜黄褐色の唾液を採取（粘液様で引糸性あり）。細胞診で少量のマクロファージと粘液を確認。唾液腺造影で損傷した唾液腺・導管を同定。CT検査で腫瘤の範囲と唾液腺との関係を評価。CBC/血液化学は通常正常。膿瘍（穿刺液：膿性）、リンパ節腫大、嚢胞性腫瘍（甲状腺嚢胞等）との鑑別が必要。舌下型（ranula）は口腔内腫脹として発見。"}
ENRICHMENTS["cat_feline_eosinophilic_pneumonia"] = {"diagnosis_ja": "咳嗽・呼吸困難・運動不耐性を呈する。CBC好酸球増多を認めることが多い。胸部X線で瀰漫性間質〜肺胞パターンの浸潤影を確認。BAL液分析で好酸球優位（>25%）を確認。糞便検査で肺虫（Aelurostrongylus abstrusus）を除外。BAL液の細菌・真菌培養。寄生虫IgEパネル検査。アレルゲン特異的IgE検査（環境アレルゲン）。ステロイド反応性で診断的治療。猫喘息、肺虫感染、アレルギー性気管支肺疾患との鑑別が必要。"}
ENRICHMENTS["cat_feline_lipoma"] = {"diagnosis_ja": "皮下の柔らかい可動性腫瘤として触知。無痛性で緩徐に増大。FNA細胞診で成熟脂肪細胞の集簇を確認（確定的）。犬と比較して猫のリポーマは稀であり、脂肪肉腫の可能性を慎重に評価。腫瘤のサイズ・位置・成長速度を記録。浸潤性リポーマの場合CT/MRIで範囲を評価。脂肪肉腫（細胞異型性あり）、線維肉腫、注射部位肉腫との鑑別が必要。猫の皮下腫瘤はFISS（ワクチン関連肉腫）の除外が重要。"}
ENRICHMENTS["cat_feline_liposarcoma"] = {"diagnosis_ja": "皮下〜深部軟部組織の硬い腫瘤として触知。リポーマより硬く、急速に増大する傾向。FNA細胞診で異型性のある脂肪芽細胞を認める。切除生検による組織病理で確定（高分化型〜未分化型の分類）。CT/MRIで腫瘤の浸潤範囲・周囲組織との関係を術前評価。胸部X線で肺転移を検索。CBC/血液化学は通常正常。腫瘤マージン評価が予後に重要。リポーマ、線維肉腫、注射部位肉腫との鑑別が必要。"}
ENRICHMENTS["cat_feline_melanoma"] = {"diagnosis_ja": "皮膚・口腔内・眼球の色素沈着腫瘤を認める。口腔内メラノーマは高悪性度。FNA細胞診でメラニン顆粒を含む紡錘形〜類円形細胞を確認（無色素性の場合は診断困難）。免疫組織化学（Melan-A、S100、PNL-2）で確定。口腔内病変では骨浸潤の評価にCT/歯科X線。所属リンパ節のFNA検査でステージング。胸部X線/腹部超音波で遠隔転移を検索。虹彩メラノーシス、扁平上皮癌、肥満細胞腫との鑑別が必要。"}
ENRICHMENTS["cat_feline_apocrine_gland_cyst"] = {"diagnosis_ja": "皮下の波動性嚢胞として触知。透明〜淡青色の液体を含む。好発部位は頭部・頸部・四肢。穿刺吸引で漿液性の液体を採取。細胞診で少量の上皮細胞と漿液を確認。超音波で嚢胞性構造（薄壁・無エコー内容物）を確認。再発する場合は嚢胞壁を含めた切除生検を実施。組織病理で二層性のアポクリン上皮被覆を確認。唾液腺粘液嚢胞、膿瘍、嚢胞性腫瘍（基底細胞腫瘍等）との鑑別が必要。"}
ENRICHMENTS["cat_feline_squamous_cell_carcinoma_nasal_planum"] = {"diagnosis_ja": "鼻鏡部の痂皮・潰瘍・紅斑を認める。白色〜薄毛の猫に好発（紫外線関連）。初期は日光性皮膚炎として見過ごされやすい。病変部の生検による組織病理で確定（上皮の浸潤性増殖、角化、細胞異型性）。前癌病変（光線角化症/上皮内癌）からの進行を評価。CT検査で鼻腔・副鼻腔への浸潤範囲を確認。所属リンパ節のFNA検査。外傷、FHV-1皮膚炎、好酸球性肉芽腫、クリプトコッカス症との鑑別が必要。"}
ENRICHMENTS["cat_feline_paraneoplastic_syndrome"] = {"diagnosis_ja": "腫瘍の直接浸潤によらない全身徴候を呈する。高Ca血症（リンパ腫、SCC：PTHrP産生）、低血糖（インスリノーマ、肝細胞癌）、多血症（腎腫瘍：EPO産生）、対称性脱毛（膵腺癌）、末梢神経障害、発熱等。血液化学で異常値の検出が端緒。原発腫瘍の検索（胸腹部画像検査、全身CT）が必須。腫瘍マーカー（PTHrP、インスリン、EPO）の測定。内分泌疾患、感染症、自己免疫疾患との鑑別が必要。"}
ENRICHMENTS["cat_feline_methemoglobinemia"] = {"diagnosis_ja": "チアノーゼ・粘膜の褐色調変色・呼吸困難・頻脈を呈する。酸素投与に反応しないチアノーゼが特徴。アセトアミノフェン、ベンゾカイン、ナフタレン等の暴露歴を確認。パルスオキシメトリーは偽低値（約85%で固定）。動脈血がチョコレートブラウン色（酸素暴露で赤変しない）。コオキシメトリーでMetHb%を測定（>15%で症状出現）。ハインツ小体形成を血液塗抹で確認。CBC PCV低下（溶血性貧血合併時）。心肺疾患、貧血との鑑別が必要。"}
ENRICHMENTS["cat_feline_transfusion_reaction"] = {"diagnosis_ja": "輸血中〜輸血後の発熱・嘔吐・蕁麻疹・頻脈・呼吸困難・低血圧を認める。急性溶血反応ではヘモグロビン血症・ヘモグロビン尿を呈する。輸血前のクロスマッチ検査結果を確認。輸血後のPCV低下・T-Bil上昇・LDH上昇は溶血を示唆。直接クームス試験陽性。輸血関連急性肺障害（TRALI）ではX線で肺水腫パターン。血液型判定（A/B/AB）の再確認。遅延型反応（3-14日後）は発熱・PCV低下で疑う。敗血症、アナフィラキシーとの鑑別が必要。"}
ENRICHMENTS["cat_feline_von_willebrand_disease"] = {"diagnosis_ja": "過度の出血傾向（鼻出血、歯肉出血、術後出血、皮下出血）を認める。PT正常、APTT正常〜軽度延長。血小板数正常。buccal mucosal bleeding time（BMBT）延長で一次止血異常を示唆。血漿vWF:Ag測定で低値を確認。vWFマルチマー分析でtype分類。PFA-100閉鎖時間延長は補助的。猫のvWDは犬より稀。血小板機能異常症、血友病A/B、DIC、ラット毒中毒との鑑別が必要。家系調査と遺伝カウンセリング。"}
ENRICHMENTS["cat_feline_hemophilia_a"] = {"diagnosis_ja": "過度の出血傾向（関節内出血、筋肉内出血、術後出血、臍帯出血）を認める。若齢オス猫に発症（X連鎖劣性遺伝）。APTT延長（PT正常）が特徴。第VIII因子活性の定量測定で低値〜欠損を確認。混合試験でAPTT補正を確認（インヒビターの除外）。CBC血小板数正常。BMBT正常（一次止血は正常）。血友病B（第IX因子）、vWD、DICとの鑑別が必要。保因者メス猫の同定には遺伝子検査が有用。"}
ENRICHMENTS["cat_feline_evans_syndrome"] = {"diagnosis_ja": "IMHA（貧血・黄疸・蒼白粘膜）とITP（紫斑・点状出血・粘膜出血）を同時に呈する。CBC再生性貧血+血小板減少。球状赤血球・自己凝集を血液塗抹で確認。直接クームス試験陽性。骨髄穿刺で赤血球系過形成・巨核球数正常〜増加を確認（末梢破壊型）。FeLV/FIV検査で感染性原因を除外。抗核抗体（ANA）でSLEを評価。リンパ腫、ヘモプラズマ症、DICとの鑑別が必要。Evans症候群は単独のIMHA/ITPより予後不良。"}
ENRICHMENTS["cat_feline_pure_red_cell_aplasia"] = {"diagnosis_ja": "重度の非再生性貧血（PCV<15%、網赤血球数<10,000/μL）を呈する。白血球・血小板数は正常。骨髄穿刺で赤芽球系前駆細胞の著明な減少〜消失を確認（骨髄球系・巨核球系は正常）。FeLV検査（FeLV-C サブグループが赤芽球癆を引き起こす）。パルボウイルスPCR検査。抗赤芽球抗体検査は研究段階。薬剤歴確認（クロラムフェニコール、エストロゲン）。FeLV関連貧血、骨髄異形成、再生不良性貧血との鑑別が必要。"}
ENRICHMENTS["cat_feline_myelodysplastic_syndrome"] = {"diagnosis_ja": "非再生性貧血・好中球減少・血小板減少を呈する（1-3系統の血球減少）。末梢血塗抹で異形成所見（巨赤芽球、過分葉好中球、微小巨核球）を確認。骨髄穿刺/生検で1系統以上の異形成（核の非同期成熟、環状鉄芽球、巨赤芽球変化）を確認。芽球比率により分類（RAEB等）。FeLV検査は必須（FeLV関連MDSが多い）。FIV検査。白血病への移行リスクを評価。再生不良性貧血、急性白血病、PRCA、鉄欠乏性貧血との鑑別が必要。"}
ENRICHMENTS["cat_feline_multiple_myeloma"] = {"diagnosis_ja": "骨痛・跛行・病的骨折、蛋白尿、出血傾向を呈する。蛋白電気泳動でモノクローナルγグロブリン血症（Mスパイク）を確認。骨X線で多発性の打ち抜き様溶骨性病変を検索。骨髄穿刺で形質細胞>10%を確認。尿中ベンスジョーンズ蛋白（遊離軽鎖）の検出。血液化学で高Ca血症、BUN/Cre上昇を認めることがある。血液粘稠度上昇による過粘稠度症候群（視力障害、出血）を評価。リンパ腫、慢性炎症、FIPとの鑑別が必要。"}
ENRICHMENTS["cat_feline_histiocytic_sarcoma"] = {"diagnosis_ja": "急速に増大する皮下〜内臓腫瘤を認める。播種性では肝脾腫・リンパ節腫大・肺浸潤を呈する。FNA細胞診で大型の多形性組織球（腎臓型核、豊富な細胞質、貪食像）を確認。免疫組織化学でCD18+、CD11d+、MHC-II+を確認。CBC汎血球減少（骨髄浸潤時）。血液化学で肝酵素上昇を認める。胸部X線/腹部超音波/CTで全身的なステージングを実施。リンパ腫、線維肉腫、肥満細胞腫との鑑別が必要。予後は不良。"}
ENRICHMENTS["cat_feline_leiomyosarcoma"] = {"diagnosis_ja": "消化管（胃・小腸・大腸）の平滑筋由来の腫瘤を形成。嘔吐・下痢・血便・体重減少を呈する。腹部超音波で腸管壁の偏心性腫瘤を確認。CT検査で腫瘤の範囲・転移を評価。FNA細胞診で紡錘形細胞を認める（GISTとの鑑別は困難）。確定は切除生検による組織病理（免疫組織化学：平滑筋アクチン+、デスミン+、c-Kit-でGISTと鑑別）。腸管リンパ腫、GIST、線維肉腫との鑑別が必要。"}
ENRICHMENTS["cat_feline_gastrointestinal_stromal_tumor_gist"] = {"diagnosis_ja": "消化管のカハール介在細胞由来の腫瘍。嘔吐・食欲不振・体重減少・消化管出血を呈する。腹部超音波で胃壁〜腸管壁の低エコー腫瘤を確認。CT検査で腫瘤のサイズ・転移を評価。FNA細胞診で紡錘形細胞を認める。確定は組織病理と免疫組織化学（c-Kit/CD117陽性、DOG1陽性、平滑筋アクチン陰性〜弱陽性）。KIT変異の遺伝子検査はイマチニブ感受性予測に有用。平滑筋肉腫、リンパ腫、腺癌との鑑別が必要。"}
ENRICHMENTS["cat_feline_choroid_plexus_tumor"] = {"diagnosis_ja": "水頭症に伴う神経症状（旋回運動、意識障害、視力喪失、痙攣）を呈する。MRIで脳室内の造影増強腫瘤と脳室拡大を確認。CSF分析で蛋白上昇・腫瘍細胞を検出（腫瘍播種の評価）。脈絡叢乳頭腫（良性）vs脈絡叢癌（悪性）の鑑別は組織病理による。CT検査で石灰化を伴う腫瘤を確認できることがある。脳室内髄膜腫、上衣腫、リンパ腫との鑑別が必要。水頭症の程度が予後に関連する。"}
ENRICHMENTS["cat_feline_osteochondroma"] = {"diagnosis_ja": "骨表面の限局性骨性隆起として触知。若齢猫に好発するが成猫発症は猫特有（FeLV関連多発性骨軟骨腫症）。X線で骨表面から突出する骨性腫瘤（軟骨帽を有する）を確認。CT検査で腫瘤の正確な位置と周囲構造との関係を評価。FeLV検査（猫の多発性骨軟骨腫はFeLV関連が多い）。確定は組織病理（正常な骨軟骨構造を持つ外骨腫）。骨肉腫、軟骨肉腫、骨膜増殖性病変との鑑別が必要。悪性転化のモニタリングが重要。"}
ENRICHMENTS["cat_feline_chondrosarcoma"] = {"diagnosis_ja": "骨格系（扁平骨・四肢骨）の硬い腫瘤として触知。跛行・局所腫脹・疼痛を認める。X線で溶骨性〜混合性の骨病変と軟部組織腫瘤を確認。CT検査で腫瘤の範囲・骨破壊パターンを詳細評価。FNA細胞診で軟骨基質中の異型性軟骨細胞を確認（確定は困難な場合あり）。切除生検による組織病理で確定（悪性軟骨細胞の増殖、基質のアルシアンブルー染色陽性）。胸部X線で肺転移を検索。骨肉腫、線維肉腫との鑑別が必要。"}
ENRICHMENTS["cat_feline_angiomatosis"] = {"diagnosis_ja": "皮膚・皮下の多発性血管性結節（赤紫色〜暗赤色）を認める。肝臓・脾臓にも発生。FNA細胞診で血液成分と血管内皮細胞を確認。切除生検による組織病理で良性血管増殖を確認（血管肉腫との鑑別が重要：異型性の程度、核分裂像の頻度）。腹部超音波で肝脾病変を検索。FeLV検査（FeLV関連血管増殖の可能性）。CBC/血液化学で貧血（出血性）を評価。血管肉腫、肥満細胞腫、カポジ様病変との鑑別が必要。"}
ENRICHMENTS["cat_feline_hemangiopericytoma"] = {"diagnosis_ja": "四肢の皮下に発生する硬い結節性腫瘤を触知。緩徐に増大し、局所浸潤性が高い。FNA細胞診で紡錘形細胞を認める（特異性は低い）。切除生検による組織病理で確定（血管周囲の紡錘形細胞が渦巻き状に配列：perivascular pattern）。免疫組織化学（ビメンチン+、平滑筋アクチン-/+）。CT/MRIで腫瘤の範囲を術前評価。広範切除のマージン評価が予後に重要。線維肉腫、末梢神経鞘腫、注射部位肉腫との鑑別が必要。"}
ENRICHMENTS["cat_feline_insulinoma-related_hypoglycemia"] = {"diagnosis_ja": "発作的な脱力・振戦・痙攣・失神（空腹時や運動後に悪化）を認める。血糖値<60mg/dLを繰り返し確認。低血糖時の同時測定で血清インスリン不適切高値（>20μIU/mL）を確認（amended insulin:glucose ratio上昇）。腹部超音波で膵臓内の低エコー小結節を検索（検出困難な場合が多い）。CT造影で膵腫瘤の検出感度が向上。肝酵素上昇を伴うことがある。肝不全、敗血症、アジソン病、腎不全性低血糖との鑑別が必要。"}
ENRICHMENTS["cat_feline_congenital_portosystemic_shunt"] = {"diagnosis_ja": "若齢猫の発育不良・食後の神経症状（流涎、異常行動、痙攣）・多飲多尿・銅色虹彩を認める。血液化学で低BUN、低Alb、低血糖、肝酵素軽度上昇を認める。総胆汁酸（空腹時+食後2時間）の著明な上昇で肝機能異常を確認。NH3上昇。腹部超音波カラードプラで異常血管を検出。CT血管造影（門脈造影相）でシャント血管の走行を確定。尿酸アンモニウム結晶を尿検査で確認することがある。肝炎、てんかん、中毒との鑑別が必要。"}
ENRICHMENTS["cat_feline_acquired_myasthenia_gravis"] = {"diagnosis_ja": "運動不耐性・四肢脱力・嚥下困難・巨大食道・顔面筋脱力を認める。運動負荷で症状悪化、休息で改善する反復性パターンが特徴。エドロフォニウム（テンシロン）試験で一過性の筋力回復を確認。血清AChR抗体価上昇で確定。反復神経刺激検査で漸減反応（decremental response）を確認。胸部X線で巨大食道と吸引性肺炎を評価。CT検査で前縦隔腫瘤（胸腺腫合併）を検索。多発性筋炎、低K血症性筋症との鑑別が必要。"}
ENRICHMENTS["cat_feline_dermatomyositis"] = {"diagnosis_ja": "皮膚病変（顔面・耳介・四肢遠位の紅斑・脱毛・痂皮）と筋炎（筋肉痛・四肢脱力・嚥下困難）を合併。CK上昇で筋障害を確認。筋電図で筋原性異常を評価。皮膚生検で界面皮膚炎（基底層の液状変性）を確認。筋生検で筋線維の壊死・再生と炎症細胞浸潤を認める。ANA/抗Mi-2抗体は研究段階。FIV/FeLV検査で免疫状態を確認。SLE、多発性筋炎、好酸球性皮膚炎との鑑別が必要。"}
ENRICHMENTS["cat_feline_polymyositis"] = {"diagnosis_ja": "全身性の筋肉痛・四肢脱力・運動不耐性・嚥下困難を呈する。CK著明上昇（>5,000U/L）で筋障害を確認。AST/LDH上昇も伴う。筋電図で筋原性異常パターン（フィブリレーション電位、鋭陽性波）を確認。確定診断は筋生検（多発性の筋線維壊死・再生とリンパ球/形質細胞浸潤）。MRIで炎症性筋変化のT2高信号を評価。トキソプラズマIgM/IgG検査。FIV/FeLV検査。甲状腺機能検査。重症筋無力症、低K血症性筋症との鑑別が必要。"}
ENRICHMENTS["cat_feline_masticatory_muscle_myositis"] = {"diagnosis_ja": "開口困難（開口不能〜制限）・咀嚼筋の腫脹（急性期）〜萎縮（慢性期）を認める。急性期は疼痛を伴い、慢性期は線維化による開口制限が進行。CK上昇（急性期）。2M筋線維抗体検査が確定的（犬で確立、猫は報告少ない）。筋電図で咀嚼筋の筋原性異常を確認。側頭筋/咬筋の生検で2M筋線維の壊死・リンパ球浸潤を確認。CT/MRIで咀嚼筋の造影増強・萎縮を評価。三叉神経炎、顎関節疾患、口腔腫瘍との鑑別が必要。"}

def apply_enrichments() -> None:
    for attempt in range(3):
        try:
            with open(JSON_PATH, encoding="utf-8") as f:
                content = f.read()
            decoder = json.JSONDecoder()
            data, _ = decoder.raw_decode(content)
            break
        except (json.JSONDecodeError, ValueError):
            if attempt < 2:
                time.sleep(5)
            else:
                raise
    updated = 0
    for entry in data:
        eid = entry.get("id")
        if eid in ENRICHMENTS:
            for k, v in ENRICHMENTS[eid].items():
                entry[k] = v
            updated += 1
    with open(JSON_PATH, "w", encoding="utf-8") as f:
        json.dump(data, f, ensure_ascii=False, indent=2)
    print(f"Updated {updated}/{len(ENRICHMENTS)} entries")

if __name__ == "__main__":
    apply_enrichments()
